#!name=穷游
#!desc=fmz200/wool_scripts · 某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思

[MITM]
hostname = open.qyer.com, media.qyer.com

[Rewrite]
request if ${url} ~= /^https?:\/\/open\.qyer\.com\/qyer\/startpage\//i then reject(200)
request if ${url} ~= /^https?:\/\/open\.qyer\.com\/qyer\/config\/get/i then reject(404)
request if ${url} ~= /^https?:\/\/media\.qyer\.com\/ad\//i then reject(404)
